#!/usr/bin/env python3
from pathlib import Path
import base64,zlib,shutil,subprocess,sys
from datetime import datetime

PAYLOADS={}
PAYLOADS['app/dashboard/ui.tsx'] = """"""
PAYLOADS['components/sidebar.tsx'] = """"""
PAYLOADS['components/mobile-nav.tsx'] = """"""
CSS=""""""
START="/* AV_V2_2_COACH_EXPERIENCE_START */"
END="/* AV_V2_2_COACH_EXPERIENCE_END */"

def unpack(x):
    return zlib.decompress(base64.b64decode(x)).decode("utf-8")

root=Path.cwd()
if not (root/"package.json").exists():
    print("Run this from the coach-hours-v1 project root.")
    sys.exit(1)

stamp=datetime.now().strftime("%Y%m%d-%H%M%S")
backup=root/".av-backups"/f"pre-v2.2.0-fixed-{stamp}"

for rel in list(PAYLOADS.keys())+["app/globals.css"]:
    src=root/rel
    if src.exists():
        dst=backup/rel
        dst.parent.mkdir(parents=True,exist_ok=True)
        shutil.copy2(src,dst)

print("Backup:",backup)

for rel,encoded in PAYLOADS.items():
    dest=root/rel
    dest.parent.mkdir(parents=True,exist_ok=True)
    dest.write_text(unpack(encoded),encoding="utf-8")

css_path=root/"app/globals.css"
existing=css_path.read_text(encoding="utf-8")
if START in existing and END in existing:
    existing=existing.split(START,1)[0].rstrip()+"\n"+existing.split(END,1)[1].lstrip()
css_path.write_text(existing.rstrip()+"\n\n"+START+"\n"+unpack(CSS).strip()+"\n"+END+"\n",encoding="utf-8")

print("Installed AV Gymnastics Solutions v2.2.0 coach experience (fixed).")
print("Running production build...")
build=subprocess.run(["npm","run","build"],cwd=root)
if build.returncode:
    print("BUILD FAILED. Nothing pushed.")
    print("Backup:",backup)
    sys.exit(build.returncode)

print("BUILD PASSED.")

if "--deploy" in sys.argv:
    subprocess.run(["git","add","app/dashboard/ui.tsx","app/globals.css","components/sidebar.tsx","components/mobile-nav.tsx"],cwd=root,check=True)
    diff=subprocess.run(["git","diff","--cached","--quiet"],cwd=root)
    if diff.returncode:
        subprocess.run(["git","commit","-m","Release v2.2.0 coach experience"],cwd=root,check=True)
        subprocess.run(["git","push","origin","main"],cwd=root,check=True)
        print("Pushed to GitHub. Wait for Vercel Ready.")
    else:
        print("No changes to commit.")
